import{_ as e,o,c as i,a2 as n}from"./chunks/framework.BWuWLRhz.js";const p=JSON.parse('{"title":"Configuración de LocalSend","description":"","frontmatter":{},"headers":[],"relativePath":"es-ES/user-guide/settings/localsend.md","filePath":"es-ES/user-guide/settings/localsend.md","lastUpdated":1785993908000}'),r={name:"es-ES/user-guide/settings/localsend.md"};function t(c,a,s,l,d,u){return o(),i("div",null,[...a[0]||(a[0]=[n('<h1 id="configuracion-de-localsend" tabindex="-1">Configuración de LocalSend <a class="header-anchor" href="#configuracion-de-localsend" aria-label="Permalink to &quot;Configuración de LocalSend&quot;">​</a></h1><p>Lertaro incluye compatibilidad integrada con el protocolo oficial de <a href="https://localsend.org" target="_blank" rel="noreferrer">LocalSend</a> para la transferencia de archivos, carpetas y texto entre dispositivos en la misma red local. Accesible en <strong>Configuración → LocalSend</strong>.</p><h2 id="configuracion-basica" tabindex="-1">Configuración básica <a class="header-anchor" href="#configuracion-basica" aria-label="Permalink to &quot;Configuración básica&quot;">​</a></h2><ul><li><strong>Habilitar transferencia LocalSend</strong> —— Activa o desactiva el servicio LocalSend. Al activarse, el menú de la bandeja del sistema proporciona la opción &quot;Enviar por LocalSend...&quot; y responde al atajo global.</li><li><strong>Alias del dispositivo</strong> —— Nombre que verán otros dispositivos en la red local. Generado automáticamente a partir del nombre del equipo.</li><li><strong>Puerto</strong> —— Puerto HTTP/HTTPS para escuchar las solicitudes de transferencia entrantes (por defecto <code>53317</code>).</li></ul><h2 id="seguridad-y-cifrado" tabindex="-1">Seguridad y cifrado <a class="header-anchor" href="#seguridad-y-cifrado" aria-label="Permalink to &quot;Seguridad y cifrado&quot;">​</a></h2><ul><li><strong>Transferencia cifrada (HTTPS)</strong> —— Utiliza conexión cifrada HTTPS para la transferencia de datos (requiere compatibilidad con HTTPS en el dispositivo de destino).</li><li><strong>PIN de recepción</strong> —— Código PIN opcional necesario para la autorización de transferencias entrantes (dejar en blanco para desactivar).</li></ul><h2 id="recepcion-y-almacenamiento" tabindex="-1">Recepción y almacenamiento <a class="header-anchor" href="#recepcion-y-almacenamiento" aria-label="Permalink to &quot;Recepción y almacenamiento&quot;">​</a></h2><ul><li><strong>Guardado rápido (Guardar automáticamente)</strong> —— Acepta y guarda automáticamente los archivos recibidos sin requerir confirmación manual.</li><li><strong>Ubicación de descarga</strong> —— Directorio de destino por defecto para los archivos recibidos.</li></ul><h2 id="modos-de-envio-e-invocacion" tabindex="-1">Modos de envío e invocación <a class="header-anchor" href="#modos-de-envio-e-invocacion" aria-label="Permalink to &quot;Modos de envío e invocación&quot;">​</a></h2><ul><li><strong>Invocación por atajo</strong> —— Presiona <strong><code>Ctrl+S</code></strong> por defecto (configurable en <a href="./hotkeys-page.html">Atajos</a>) o selecciona &quot;Enviar por LocalSend...&quot; en el menú de la bandeja.</li><li><strong>Cambio de modo</strong> —— La ventana de envío permite alternar entre [ Enviar archivos / carpetas ] y [ Enviar texto ].</li></ul>',10)])])}const m=e(r,[["render",t]]);export{p as __pageData,m as default};
